// src/db/migration-runner.ts
var MigrationRunner = class {
  db;
  migrations;
  dbName;
  constructor(db, migrations, dbName) {
    this.db = db;
    this.migrations = [...migrations].sort((a, b) => a.version - b.version);
    this.dbName = dbName;
    this.ensureMigrationsTable();
  }
  ensureMigrationsTable() {
    this.db.exec(`
			CREATE TABLE IF NOT EXISTS _migrations (
				version    INTEGER PRIMARY KEY,
				name       TEXT    NOT NULL,
				applied_at TEXT    NOT NULL
			)
		`);
  }
  getAppliedVersions() {
    const rows = this.db.prepare("SELECT version FROM _migrations ORDER BY version").all();
    return new Set(rows.map((r3) => r3.version));
  }
  applyMigration(migration) {
    console.log(
      `[db:${this.dbName}] Applying migration ${migration.version}: ${migration.name}`
    );
    const run = this.db.transaction(() => {
      this.db.exec(migration.up);
      this.db.prepare(
        "INSERT INTO _migrations (version, name, applied_at) VALUES (?, ?, ?)"
      ).run(migration.version, migration.name, (/* @__PURE__ */ new Date()).toISOString());
    });
    try {
      run();
      console.log(
        `[db:${this.dbName}] Migration ${migration.version} applied successfully.`
      );
    } catch (err) {
      throw new Error(
        `[db:${this.dbName}] Migration ${migration.version} (${migration.name}) failed \u2014 ` + (err instanceof Error ? err.message : String(err))
      );
    }
  }
  runPending() {
    const applied = this.getAppliedVersions();
    const pending = this.migrations.filter((m) => !applied.has(m.version));
    if (pending.length === 0) return;
    console.log(
      `[db:${this.dbName}] Running ${pending.length} pending migration(s)...`
    );
    for (const migration of pending) {
      this.applyMigration(migration);
    }
    console.log(`[db:${this.dbName}] All migrations up to date.`);
  }
  rollbackLast() {
    const last = this.db.prepare(
      "SELECT version, name FROM _migrations ORDER BY version DESC LIMIT 1"
    ).get();
    if (!last) {
      console.log(`[db:${this.dbName}] No migrations to roll back.`);
      return;
    }
    const migration = this.migrations.find((m) => m.version === last.version);
    if (!migration) {
      throw new Error(
        `[db:${this.dbName}] Migration ${last.version} not found in migration list.`
      );
    }
    if (!migration.down) {
      throw new Error(
        `[db:${this.dbName}] Migration ${last.version} has no "down" SQL \u2014 cannot roll back.`
      );
    }
    const rollback = this.db.transaction(() => {
      this.db.exec(migration.down);
      this.db.prepare("DELETE FROM _migrations WHERE version = ?").run(last.version);
    });
    try {
      rollback();
      console.log(
        `[db:${this.dbName}] Migration ${last.version} rolled back successfully.`
      );
    } catch (err) {
      throw new Error(
        `[db:${this.dbName}] Rollback of migration ${last.version} failed \u2014 ` + (err instanceof Error ? err.message : String(err))
      );
    }
  }
  getStatus() {
    const applied = this.db.prepare(
      "SELECT version, name, applied_at FROM _migrations ORDER BY version"
    ).all();
    const appliedMap = new Map(applied.map((m) => [m.version, m]));
    return this.migrations.map((m) => {
      const record = appliedMap.get(m.version);
      return {
        version: m.version,
        name: m.name,
        status: record ? "applied" : "pending",
        appliedAt: record?.applied_at
      };
    });
  }
};

// src/db/parse-migration-sql.ts
function parseMigrationSql(content) {
  const downSplit = content.split(/^--\s*DOWN\s*$/im);
  const upSection = downSplit[0];
  const downSection = downSplit[1];
  const up = upSection.replace(/^--\s*UP\s*$/im, "").trim();
  const down = downSection ? downSection.trim() : void 0;
  return { up, down };
}

// src/migrations/001_initial_schema.sql
var initial_schema_default = "-- Migration 001: Initial trading database schema\n-- Sets up all tables used by TradingStore, TradeJournal, and CandleStore.\n-- All three classes share the same SQLite database file.\n--\n-- positions       \u2014 open/closed trading positions\n-- equity_snapshots \u2014 equity curve over time\n-- price_alerts    \u2014 user-set price level notifications\n-- trade_log       \u2014 record of every order placed\n-- settings        \u2014 key/value config (max_trade_usd, paper_mode, etc.)\n-- signal_log      \u2014 strategy-generated signals with their outcome\n-- strategy_trades \u2014 completed trades tied back to signals (for performance analysis)\n-- candles         \u2014 OHLCV price history by symbol + timeframe\n\n-- UP\n\n-- \u2500\u2500 TradingStore tables \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nCREATE TABLE IF NOT EXISTS positions (\n	id               TEXT NOT NULL PRIMARY KEY,\n	symbol           TEXT NOT NULL,\n	side             TEXT NOT NULL,\n	entryPrice       REAL NOT NULL,\n	qty              REAL NOT NULL,\n	currentPrice     REAL,\n	pnl              REAL,\n	status           TEXT NOT NULL DEFAULT 'open',\n	openedAt         TEXT NOT NULL,\n	closedAt         TEXT,\n	stopLoss         REAL,\n	takeProfit       REAL,\n	trailingStopPct  REAL,\n	trailingStopHigh REAL\n);\n\nCREATE TABLE IF NOT EXISTS equity_snapshots (\n	timestamp TEXT NOT NULL PRIMARY KEY,\n	equity    REAL NOT NULL\n);\n\nCREATE TABLE IF NOT EXISTS price_alerts (\n	id          TEXT    NOT NULL PRIMARY KEY,\n	symbol      TEXT    NOT NULL,\n	condition   TEXT    NOT NULL,\n	targetPrice REAL    NOT NULL,\n	triggered   INTEGER NOT NULL DEFAULT 0,\n	createdAt   TEXT    NOT NULL,\n	triggeredAt TEXT\n);\n\nCREATE TABLE IF NOT EXISTS trade_log (\n	id        TEXT NOT NULL PRIMARY KEY,\n	symbol    TEXT NOT NULL,\n	side      TEXT NOT NULL,\n	type      TEXT NOT NULL,\n	qty       REAL NOT NULL,\n	price     REAL NOT NULL,\n	total     REAL NOT NULL,\n	orderId   TEXT,\n	createdAt TEXT NOT NULL\n);\n\n-- Key/value settings (max_trade_usd, daily_limit_usd, paper_mode)\nCREATE TABLE IF NOT EXISTS settings (\n	key   TEXT NOT NULL PRIMARY KEY,\n	value TEXT NOT NULL\n);\n\n-- \u2500\u2500 TradeJournal tables \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nCREATE TABLE IF NOT EXISTS signal_log (\n	id               TEXT NOT NULL PRIMARY KEY,\n	strategyName     TEXT NOT NULL,\n	symbol           TEXT NOT NULL,\n	direction        TEXT NOT NULL,\n	confidence       REAL NOT NULL,\n	reason           TEXT NOT NULL,\n	entryPrice       REAL NOT NULL,\n	qty              REAL NOT NULL,\n	stopLoss         REAL NOT NULL,\n	takeProfit       REAL NOT NULL,\n	status           TEXT NOT NULL DEFAULT 'generated',\n	rejectionReasons TEXT,\n	createdAt        TEXT NOT NULL\n);\n\nCREATE INDEX IF NOT EXISTS idx_signal_log_strategy\n	ON signal_log (strategyName, createdAt DESC);\nCREATE INDEX IF NOT EXISTS idx_signal_log_status\n	ON signal_log (status, createdAt DESC);\n\nCREATE TABLE IF NOT EXISTS strategy_trades (\n	id           TEXT NOT NULL PRIMARY KEY,\n	signalId     TEXT NOT NULL,\n	strategyName TEXT NOT NULL,\n	symbol       TEXT NOT NULL,\n	direction    TEXT NOT NULL,\n	entryPrice   REAL NOT NULL,\n	exitPrice    REAL,\n	qty          REAL NOT NULL,\n	pnl          REAL,\n	rMultiple    REAL,\n	exitReason   TEXT,\n	enteredAt    TEXT NOT NULL,\n	exitedAt     TEXT,\n	FOREIGN KEY (signalId) REFERENCES signal_log(id)\n);\n\nCREATE INDEX IF NOT EXISTS idx_strategy_trades_name\n	ON strategy_trades (strategyName, enteredAt DESC);\n\n-- \u2500\u2500 CandleStore table \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nCREATE TABLE IF NOT EXISTS candles (\n	symbol    TEXT    NOT NULL,\n	timeframe TEXT    NOT NULL,\n	openTime  INTEGER NOT NULL,\n	open      REAL    NOT NULL,\n	high      REAL    NOT NULL,\n	low       REAL    NOT NULL,\n	close     REAL    NOT NULL,\n	volume    REAL    NOT NULL,\n	PRIMARY KEY (symbol, timeframe, openTime)\n);\n\nCREATE INDEX IF NOT EXISTS idx_candles_lookup\n	ON candles (symbol, timeframe, openTime DESC);\n\n-- \u2500\u2500 Default safety settings \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n-- These are conservative defaults. Real-money values must be set in config.\n-- INSERT OR IGNORE means this only runs on a fresh database \u2014\n-- existing settings are never overwritten by a migration.\n\nINSERT OR IGNORE INTO settings (key, value) VALUES ('max_trade_usd',   '25');\nINSERT OR IGNORE INTO settings (key, value) VALUES ('daily_limit_usd', '100');\nINSERT OR IGNORE INTO settings (key, value) VALUES ('paper_mode',      'true');\n\n-- DOWN\n\nDROP INDEX IF EXISTS idx_candles_lookup;\nDROP TABLE IF EXISTS candles;\nDROP INDEX IF EXISTS idx_strategy_trades_name;\nDROP TABLE IF EXISTS strategy_trades;\nDROP INDEX IF EXISTS idx_signal_log_status;\nDROP INDEX IF EXISTS idx_signal_log_strategy;\nDROP TABLE IF EXISTS signal_log;\nDROP TABLE IF EXISTS settings;\nDROP TABLE IF EXISTS trade_log;\nDROP TABLE IF EXISTS price_alerts;\nDROP TABLE IF EXISTS equity_snapshots;\nDROP TABLE IF EXISTS positions;\n";

// src/migrations/002_paper_trading.sql
var paper_trading_default = "-- Migration 002: Paper trading support\n-- Adds isPaper flag to positions and trade_log, plus a virtual portfolio table.\n\n-- UP\n\n-- Add isPaper column to positions (default true = paper mode is the safe default)\nALTER TABLE positions ADD COLUMN isPaper INTEGER NOT NULL DEFAULT 1;\n\n-- Add isPaper column to trade_log\nALTER TABLE trade_log ADD COLUMN isPaper INTEGER NOT NULL DEFAULT 1;\n\n-- Virtual portfolio for paper trading \u2014 each row is a currency balance (USDT, BTC, ETH, etc.)\nCREATE TABLE IF NOT EXISTS paper_balances (\n	currency TEXT NOT NULL PRIMARY KEY,\n	balance  REAL NOT NULL DEFAULT 0\n);\n\n-- Seed default paper balance ($1000 USDT)\nINSERT OR IGNORE INTO paper_balances (currency, balance) VALUES ('USDT', 1000);\n\n-- Add virtual_balance_usd setting\nINSERT OR IGNORE INTO settings (key, value) VALUES ('virtual_balance_usd', '1000');\n\n-- DOWN\n\nDROP TABLE IF EXISTS paper_balances;\n";

// src/migrations/003_backtest_results.sql
var backtest_results_default = "-- Migration 003: Backtest results storage\n-- Stores completed backtest runs for comparison over time.\n\n-- UP\n\nCREATE TABLE IF NOT EXISTS backtest_results (\n	id TEXT PRIMARY KEY,\n	strategy TEXT NOT NULL,\n	symbol TEXT NOT NULL,\n	timeframe TEXT NOT NULL,\n	startDate TEXT NOT NULL,\n	endDate TEXT NOT NULL,\n	startingEquity REAL NOT NULL,\n	finalEquity REAL NOT NULL,\n	totalPnl REAL NOT NULL,\n	totalReturnPct REAL NOT NULL,\n	winRate REAL NOT NULL,\n	sharpeRatio REAL NOT NULL,\n	maxDrawdownPct REAL NOT NULL,\n	totalTrades INTEGER NOT NULL,\n	resultJson TEXT NOT NULL,\n	createdAt TEXT NOT NULL\n);\n\nCREATE INDEX IF NOT EXISTS idx_bt_strategy ON backtest_results (strategy, symbol, createdAt DESC);\n\n-- DOWN\n\nDROP INDEX IF EXISTS idx_bt_strategy;\nDROP TABLE IF EXISTS backtest_results;\n";

// src/migrations/004_circuit_breaker_persistence.sql
var circuit_breaker_persistence_default = "-- Migration 004: Circuit breaker persistence and stop-monitor checkpointing\n--\n-- circuit_breaker_state      \u2014 persists trip state for each trading risk breaker\n--                              so breakers survive process restarts / crashes.\n--\n-- stop_monitor_checkpoints   \u2014 per-position checkpoint updated every monitoring\n--                              cycle; used on startup to detect and act on gaps.\n\n-- UP\n\n-- One row per logical breaker. Trips, counters, and cooldowns survive restarts.\n-- peak_equity is meaningful for the 'drawdown' and 'velocity' breakers.\n-- consecutive_losses is meaningful for the 'consecutive_loss' breaker.\nCREATE TABLE IF NOT EXISTS circuit_breaker_state (\n	id                 INTEGER PRIMARY KEY AUTOINCREMENT,\n	breaker_type       TEXT    NOT NULL UNIQUE,\n	trip_count         INTEGER NOT NULL DEFAULT 0,\n	is_tripped         INTEGER NOT NULL DEFAULT 0,\n	trip_reason        TEXT,\n	tripped_at         TEXT,\n	cooldown_until     TEXT,\n	peak_equity        REAL    NOT NULL DEFAULT 0,\n	consecutive_losses INTEGER NOT NULL DEFAULT 0,\n	last_updated       TEXT    NOT NULL\n);\n\n-- Pre-populate rows so runtime UPDATE statements always find a target row.\nINSERT OR IGNORE INTO circuit_breaker_state\n	(breaker_type, trip_count, is_tripped, peak_equity, consecutive_losses, last_updated)\nVALUES ('consecutive_loss', 0, 0, 0, 0, datetime('now'));\n\nINSERT OR IGNORE INTO circuit_breaker_state\n	(breaker_type, trip_count, is_tripped, peak_equity, consecutive_losses, last_updated)\nVALUES ('drawdown', 0, 0, 0, 0, datetime('now'));\n\nINSERT OR IGNORE INTO circuit_breaker_state\n	(breaker_type, trip_count, is_tripped, peak_equity, consecutive_losses, last_updated)\nVALUES ('policy_volume', 0, 0, 0, 0, datetime('now'));\n\nINSERT OR IGNORE INTO circuit_breaker_state\n	(breaker_type, trip_count, is_tripped, peak_equity, consecutive_losses, last_updated)\nVALUES ('velocity', 0, 0, 0, 0, datetime('now'));\n\n-- Index for efficient velocity-window queries on the existing equity_snapshots table.\nCREATE INDEX IF NOT EXISTS idx_equity_snapshots_ts\n	ON equity_snapshots (timestamp DESC);\n\n-- Per-position checkpoints for stop-monitor crash recovery.\n-- Updated after every monitoring cycle; read on startup to detect unmonitored gaps.\nCREATE TABLE IF NOT EXISTS stop_monitor_checkpoints (\n	position_id        TEXT    NOT NULL PRIMARY KEY,\n	last_checked_price REAL,\n	last_check_time    TEXT,\n	retry_count        INTEGER NOT NULL DEFAULT 0,\n	status             TEXT    NOT NULL DEFAULT 'monitoring'\n);\n\n-- DOWN\n\nDROP TABLE IF EXISTS stop_monitor_checkpoints;\nDROP INDEX IF EXISTS idx_equity_snapshots_ts;\nDROP TABLE IF EXISTS circuit_breaker_state;\n";

// src/migrations/005_submitted_orders.sql
var submitted_orders_default = "-- Migration 005: Submitted orders table for idempotency\n-- Prevents duplicate order submission when a signal is received more than once\n-- or when a timeout causes uncertainty about whether an order was placed.\n--\n-- key       \u2014 SHA-256 hash of (symbol + side + qty + type + time-window)\n-- orderId   \u2014 exchange order ID, set once the order is confirmed on exchange\n-- status    \u2014 pending (submitted, awaiting confirmation) | confirmed | failed\n-- symbol    \u2014 instrument name (e.g. BTC_USDT)\n-- createdAt \u2014 ISO timestamp for 24-hour TTL cleanup\n\n-- UP\n\nCREATE TABLE IF NOT EXISTS submitted_orders (\n	key       TEXT NOT NULL PRIMARY KEY,\n	orderId   TEXT,\n	status    TEXT NOT NULL DEFAULT 'pending',\n	symbol    TEXT NOT NULL,\n	createdAt TEXT NOT NULL\n);\n\nCREATE INDEX IF NOT EXISTS idx_submitted_orders_created\n	ON submitted_orders (createdAt);\n\n-- DOWN\n\nDROP INDEX IF EXISTS idx_submitted_orders_created;\nDROP TABLE IF EXISTS submitted_orders;\n";

// src/migrations/006_regime_session_tagging.sql
var regime_session_tagging_default = "-- Migration 006: Add regime and session tagging to signal_log and strategy_trades.\n--\n-- Enables post-hoc analysis of which market regimes and trading sessions\n-- produce the best (and worst) trades. This data powers:\n--   1. Journal regime breakdowns (which regimes are we profitable in?)\n--   2. Session quality analysis (are we trading in good windows?)\n--   3. Regime-segmented backtesting (how does a strategy perform per regime?)\n\n-- UP\n\n-- Add regime/session columns to signal_log (where signals are born)\nALTER TABLE signal_log ADD COLUMN regime TEXT;\nALTER TABLE signal_log ADD COLUMN regimeConfidence REAL;\nALTER TABLE signal_log ADD COLUMN session TEXT;\nALTER TABLE signal_log ADD COLUMN sessionFitness REAL;\n\n-- Add regime/session to strategy_trades (carried from signal at entry time)\nALTER TABLE strategy_trades ADD COLUMN regime TEXT;\nALTER TABLE strategy_trades ADD COLUMN session TEXT;\n\n-- Index for regime-based queries (journal breakdowns, performance analysis)\nCREATE INDEX IF NOT EXISTS idx_signal_log_regime\n	ON signal_log (regime, createdAt DESC);\nCREATE INDEX IF NOT EXISTS idx_strategy_trades_regime\n	ON strategy_trades (regime, enteredAt DESC);\n\n-- DOWN\n\nDROP INDEX IF EXISTS idx_strategy_trades_regime;\nDROP INDEX IF EXISTS idx_signal_log_regime;\n-- SQLite does not support DROP COLUMN prior to 3.35.0.\n-- These columns are nullable so they're safe to leave if rollback isn't possible.\n-- On SQLite >= 3.35.0:\n-- ALTER TABLE signal_log DROP COLUMN regime;\n-- ALTER TABLE signal_log DROP COLUMN regimeConfidence;\n-- ALTER TABLE signal_log DROP COLUMN session;\n-- ALTER TABLE signal_log DROP COLUMN sessionFitness;\n-- ALTER TABLE strategy_trades DROP COLUMN regime;\n-- ALTER TABLE strategy_trades DROP COLUMN session;\n";

// src/migrations/007_opus_grind_log.sql
var opus_grind_log_default = "-- Migration 007: Opus grind session log.\n--\n-- Tracks what each hourly Opus grind cycle actually did:\n-- which steps produced actionable output, trades executed,\n-- alerts set, and findings stored. Enables auditing cycle\n-- effectiveness and tuning the grind prompt over time.\n\n-- UP\n\nCREATE INDEX IF NOT EXISTS idx_positions_status_opened ON positions(status, openedAt DESC);\nCREATE INDEX IF NOT EXISTS idx_trade_log_symbol_created ON trade_log(symbol, createdAt);\n\nCREATE TABLE IF NOT EXISTS opus_grind_log (\n	id TEXT PRIMARY KEY,\n	startedAt TEXT NOT NULL,\n	completedAt TEXT,\n	durationMs INTEGER,\n	status TEXT NOT NULL DEFAULT 'running',\n	-- What the cycle found\n	marketRegime TEXT,\n	bestOpportunity TEXT,\n	portfolioEquity REAL,\n	portfolioPnl REAL,\n	drawdownPct REAL,\n	riskViolations INTEGER DEFAULT 0,\n	-- What the cycle did\n	tradeExecuted INTEGER DEFAULT 0,\n	alertsSet INTEGER DEFAULT 0,\n	memoriesStored INTEGER DEFAULT 0,\n	parameterTweaks INTEGER DEFAULT 0,\n	-- Quality metrics\n	stepsCompleted INTEGER DEFAULT 0,\n	stepsSkipped INTEGER DEFAULT 0,\n	actionsTaken INTEGER DEFAULT 0,\n	-- Full details\n	summaryJson TEXT,\n	errorMessage TEXT\n);\n\nCREATE INDEX IF NOT EXISTS idx_opus_grind_log_started\n	ON opus_grind_log (startedAt DESC);\nCREATE INDEX IF NOT EXISTS idx_opus_grind_log_status\n	ON opus_grind_log (status);\n\n-- DOWN\n\nDROP INDEX IF EXISTS idx_opus_grind_log_status;\nDROP INDEX IF EXISTS idx_opus_grind_log_started;\nDROP TABLE IF EXISTS opus_grind_log;\nDROP INDEX IF EXISTS idx_trade_log_symbol_created;\nDROP INDEX IF EXISTS idx_positions_status_opened;\n";

// src/migrations/008_fee_columns.sql
var fee_columns_default = "-- 008_fee_columns.sql\n\n-- UP\n\nALTER TABLE positions ADD COLUMN entryFee REAL NOT NULL DEFAULT 0;\nALTER TABLE positions ADD COLUMN exitFee REAL NOT NULL DEFAULT 0;\n\n-- DOWN\n\n-- SQLite does not support DROP COLUMN in older versions;\n-- these columns are harmless if left in place.\n";

// src/migrations/009_position_milestones.sql
var position_milestones_default = "-- Migration 009: Persist scale-out milestone hits\n-- Tracks which profit milestones have fired for each open position so that\n-- milestone state survives process restarts without double-scaling.\n\n-- UP\n\nCREATE TABLE IF NOT EXISTS position_milestones (\n	positionId TEXT NOT NULL,\n	profitPct  REAL NOT NULL,\n	firedAt    TEXT NOT NULL,\n	PRIMARY KEY (positionId, profitPct)\n);\n\n-- DOWN\n\nDROP TABLE IF EXISTS position_milestones;\n";

// src/migrations/010_dex_execution_metadata.sql
var dex_execution_metadata_default = "-- 010: Optional metadata for on-chain (DEX) execution alongside CEX trades.\n\n-- UP\n\nALTER TABLE trade_log ADD COLUMN executionVenue TEXT;\nALTER TABLE trade_log ADD COLUMN chain TEXT;\nALTER TABLE trade_log ADD COLUMN txSignature TEXT;\nALTER TABLE trade_log ADD COLUMN slippageBps INTEGER;\nALTER TABLE trade_log ADD COLUMN routeJson TEXT;\n\nALTER TABLE positions ADD COLUMN executionVenue TEXT;\nALTER TABLE positions ADD COLUMN chain TEXT;\nALTER TABLE positions ADD COLUMN txSignature TEXT;\nALTER TABLE positions ADD COLUMN slippageBps INTEGER;\nALTER TABLE positions ADD COLUMN routeJson TEXT;\n\n-- DOWN\n\n-- SQLite: columns left in place on rollback (harmless).\n";

// src/migrations/011_risk_monitor_and_lock_state.sql
var risk_monitor_and_lock_state_default = "-- Migration 011: persistent risk monitor and automated lock-state settings.\n--\n-- Adds an audit trail for automated risk transitions and seeds persistent\n-- runtime settings for the 2% daily-loss hard stop, 2% max drawdown lock,\n-- and fractional Kelly sizing.\n\n-- UP\n\nCREATE TABLE IF NOT EXISTS risk_monitor (\n	id TEXT NOT NULL PRIMARY KEY,\n	createdAt TEXT NOT NULL,\n	fromState TEXT NOT NULL,\n	toState TEXT NOT NULL,\n	reason TEXT NOT NULL,\n	detailJson TEXT\n);\n\nCREATE INDEX IF NOT EXISTS idx_risk_monitor_created\n	ON risk_monitor (createdAt DESC);\n\nINSERT OR IGNORE INTO settings (key, value) VALUES ('daily_loss_hardstop_pct', '0.02');\nINSERT OR IGNORE INTO settings (key, value) VALUES ('max_total_drawdown_pct', '0.02');\nINSERT OR IGNORE INTO settings (key, value) VALUES ('sizing_model', 'fractional_kelly_0.25');\nINSERT OR IGNORE INTO settings (key, value) VALUES ('trading_state', 'ACTIVE');\nINSERT OR IGNORE INTO settings (key, value) VALUES ('trading_status', 'ACTIVE');\n\n-- DOWN\n\nDELETE FROM settings WHERE key IN (\n	'daily_loss_hardstop_pct',\n	'max_total_drawdown_pct',\n	'sizing_model',\n	'trading_state',\n	'trading_status'\n);\nDROP INDEX IF EXISTS idx_risk_monitor_created;\nDROP TABLE IF EXISTS risk_monitor;\n";

// src/migrations/012_strategy_grading.sql
var strategy_grading_default = "-- Migration 012: Strategy grading & lifecycle (paper/live journal closes)\n-- Rolling profit factor, expectancy, drawdown-from-trades, regime mix;\n-- persisted runs + current lifecycle row used as sizing multiplier gate.\n\n-- UP\n\nCREATE TABLE IF NOT EXISTS strategy_grade_runs (\n	id TEXT PRIMARY KEY,\n	strategyName TEXT NOT NULL,\n	symbol TEXT NOT NULL,\n	strategyVersion TEXT NOT NULL DEFAULT '1',\n	paramsHash TEXT NOT NULL DEFAULT '',\n	computedAt TEXT NOT NULL,\n	windowStart TEXT NOT NULL,\n	windowEnd TEXT NOT NULL,\n	closedTradeCount INTEGER NOT NULL,\n	rollingProfitFactor REAL NOT NULL,\n	expectancy REAL NOT NULL,\n	winRate REAL NOT NULL,\n	maxEquityDrawdownPct REAL NOT NULL,\n	regimeBreakdownJson TEXT NOT NULL,\n	compositeScore REAL NOT NULL,\n	quartile INTEGER NOT NULL,\n	lifecycleState TEXT NOT NULL,\n	allocationMultiplier REAL NOT NULL\n);\n\nCREATE INDEX IF NOT EXISTS idx_strategy_grade_runs_name_time\n	ON strategy_grade_runs (strategyName, computedAt DESC);\n\nCREATE TABLE IF NOT EXISTS strategy_lifecycle (\n	strategyName TEXT NOT NULL,\n	symbol TEXT NOT NULL,\n	strategyVersion TEXT NOT NULL DEFAULT '1',\n	paramsHash TEXT NOT NULL DEFAULT '',\n	lifecycleState TEXT NOT NULL,\n	allocationMultiplier REAL NOT NULL,\n	lastGradeRunId TEXT,\n	updatedAt TEXT NOT NULL,\n	detailJson TEXT,\n	PRIMARY KEY (strategyName, symbol, strategyVersion, paramsHash)\n);\n\nCREATE INDEX IF NOT EXISTS idx_strategy_lifecycle_state\n	ON strategy_lifecycle (lifecycleState, updatedAt DESC);\n\n-- DOWN\n\nDROP INDEX IF EXISTS idx_strategy_lifecycle_state;\nDROP TABLE IF EXISTS strategy_lifecycle;\nDROP INDEX IF EXISTS idx_strategy_grade_runs_name_time;\nDROP TABLE IF EXISTS strategy_grade_runs;\n";

// src/migrations/013_strategy_regime_weights.sql
var strategy_regime_weights_default = "-- UP\nCREATE TABLE IF NOT EXISTS strategy_regime_weights (\n  strategy_name TEXT NOT NULL,\n  regime TEXT NOT NULL,\n  weight REAL NOT NULL DEFAULT 1.0,\n  trade_count INTEGER NOT NULL DEFAULT 0,\n  win_rate REAL NOT NULL DEFAULT 0,\n  avg_pnl REAL NOT NULL DEFAULT 0,\n  updated_at TEXT NOT NULL,\n  PRIMARY KEY (strategy_name, regime)\n);\n\n-- DOWN\nDROP TABLE IF EXISTS strategy_regime_weights;\n";

// src/migrations/014_raise_max_drawdown_threshold.sql
var raise_max_drawdown_threshold_default = "-- Migration 014: raise max_total_drawdown_pct from 0.02 to 0.07.\n--\n-- The 2% threshold seeded by migration 011 fired the automated risk lock\n-- at normal paper-trading drawdown, blocking all entries across multiple\n-- sessions despite a 10% RiskManager.maxDrawdownPct elsewhere in the system.\n-- 0.07 matches the code default in automated-risk-lock.ts and aligns the two\n-- subsystems so the lock only triggers on genuinely large drawdowns.\n--\n-- daily_loss_hardstop_pct stays at 0.02 \u2014 a 2% daily realized loss limit is\n-- intentional and unrelated to the drawdown lock that was over-firing.\n\n-- UP\n\nUPDATE settings SET value = '0.07'\n	WHERE key = 'max_total_drawdown_pct' AND value = '0.02';\n\n-- DOWN\n\nUPDATE settings SET value = '0.02'\n	WHERE key = 'max_total_drawdown_pct' AND value = '0.07';\n";

// src/migrations/015_strategy_param_tuning.sql
var strategy_param_tuning_default = "-- Migration 015: Strategy parameter tuning tables\n-- strategy_rankings: rolling 30d performance snapshots used for signal weight promotion/demotion\n-- dynamic_risk_state: persisted dynamic risk adjuster state (per portfolio, not per strategy)\n-- optimizer_results: historical optimization run results for auditing\n\n-- UP\n\nCREATE TABLE IF NOT EXISTS strategy_rankings (\n	id TEXT PRIMARY KEY,\n	strategyName TEXT NOT NULL,\n	computedAt TEXT NOT NULL,\n	windowStartMs INTEGER NOT NULL,\n	windowEndMs INTEGER NOT NULL,\n	tradeCount INTEGER NOT NULL,\n	winRate REAL NOT NULL,\n	sharpeRatio REAL NOT NULL,\n	maxDrawdownPct REAL NOT NULL,\n	totalPnl REAL NOT NULL,\n	rank INTEGER NOT NULL,\n	signalWeightMultiplier REAL NOT NULL\n);\n\nCREATE INDEX IF NOT EXISTS idx_strategy_rankings_name_time\n	ON strategy_rankings (strategyName, computedAt DESC);\n\nCREATE TABLE IF NOT EXISTS dynamic_risk_state (\n	id TEXT NOT NULL DEFAULT 'portfolio',\n	riskMultiplier REAL NOT NULL DEFAULT 1.0,\n	stopLossMultiplier REAL NOT NULL DEFAULT 1.0,\n	pausedUntilMs INTEGER NOT NULL DEFAULT 0,\n	consecutiveLosses INTEGER NOT NULL DEFAULT 0,\n	improvingSinceMs INTEGER,\n	lastUpdatedAt TEXT NOT NULL,\n	reasonJson TEXT,\n	PRIMARY KEY (id)\n);\n\nCREATE TABLE IF NOT EXISTS optimizer_results (\n	id TEXT PRIMARY KEY,\n	strategyName TEXT NOT NULL,\n	runAt TEXT NOT NULL,\n	periodDays INTEGER NOT NULL,\n	candleCount INTEGER NOT NULL,\n	paramsTestedCount INTEGER NOT NULL,\n	resultsJson TEXT NOT NULL\n);\n\nCREATE INDEX IF NOT EXISTS idx_optimizer_results_name_time\n	ON optimizer_results (strategyName, runAt DESC);\n\n-- DOWN\n\nDROP INDEX IF EXISTS idx_optimizer_results_name_time;\nDROP TABLE IF EXISTS optimizer_results;\nDROP TABLE IF EXISTS dynamic_risk_state;\nDROP INDEX IF EXISTS idx_strategy_rankings_name_time;\nDROP TABLE IF EXISTS strategy_rankings;\n";

// src/migrations/016_strategy_trades_shadow_flag.sql
var strategy_trades_shadow_flag_default = "-- Migration 016: Mark shadow trades in strategy_trades.\n--\n-- Before this migration, shadow / paper / live trades all landed in the same\n-- strategy_trades rows with no way to distinguish them. Shadow positions\n-- closing through StopMonitor never updated their exit fields either, so the\n-- learning-loop consumers (leaderboard, grader, return attribution, dynamic\n-- risk) silently mixed shadow signals with real outcomes \u2014 or excluded them\n-- entirely because exitedAt was always NULL.\n--\n-- isShadow = 1 marks rows produced by the shadow execution path. Default 0 so\n-- all existing rows continue to be treated as paper/live. Consumer queries\n-- filter on isShadow = 0 by default; shadow-only views opt in explicitly.\n\n-- UP\n\nALTER TABLE strategy_trades ADD COLUMN isShadow INTEGER NOT NULL DEFAULT 0;\n\nCREATE INDEX IF NOT EXISTS idx_strategy_trades_shadow\n	ON strategy_trades (isShadow, exitedAt DESC);\n\n-- DOWN\n\nDROP INDEX IF EXISTS idx_strategy_trades_shadow;\n\n-- SQLite cannot DROP COLUMN before 3.35; the column is harmless at default 0\n-- so leaving it in place on rollback is acceptable.\n";

// src/migrations/017_trading_indexes.sql
