    const totalReturn = (prices[n - 1] - prices[0]) / prices[0];
    const cagr = (1 + totalReturn) ** (TRADING_DAYS / n) - 1;
    const meanRet = logRets.reduce((s, r3) => s + r3, 0) / logRets.length;
