      symbol: a.symbol,
      name: a.name,
      assetClass: a.assetClass,
      startDate: a.dates[0],
      endDate: a.dates[n - 1],
      totalDays: n,
      totalReturn,
      cagr,
      annualizedVol: annVol,
      sharpeRatio: sharpe,
      sortinoRatio: sortino,
