  stopMonitor;
  eventLog;
  driftThresholdPct;
  onAlert;
  hasRun = false;
  constructor(deps) {
    this.store = deps.store;
    this.client = deps.client;
    this.stopMonitor = deps.stopMonitor;
    this.eventLog = deps.eventLog;
    this.driftThresholdPct = deps.driftThresholdPct ?? DEFAULT_DRIFT_PCT;
    this.onAlert = deps.onAlert;
  }
