      const adxTag = currentAdx != null ? ` [ADX ${currentAdx.toFixed(1)}]` : "";
      const reconcileTag = reconciled.agreed ? "" : ` [regime disagree \u2192 ${reconciled.regime}]`;
      const label = touchedLowerBand ? "Bounce off" : "Approaching";
