      const refPriceShort = touchedUpperBand ? prevPrice >= upperBand ? prevPrice : price : price;
      const stopLoss = refPriceShort + currentAtr * this.riskParams.stopLossAtrMultiplier;
      const riskDistanceShort = stopLoss - price;
