    if (bb.middle.length < SQUEEZE_LOOKBACK + 2 || closes.length < SQUEEZE_LOOKBACK + 2 || atr2.length === 0) {
      return null;
    }
    const last = candles[candles.length - 1];
    const price = closes[closes.length - 1];
