        direction: "short",
        confidence: conf,
        reason: `Squeeze breakout DOWN: bw rank ${(rank * 100).toFixed(0)}% expanding ${(curBw / prevBw).toFixed(2)}\xD7, close below lower band`,
        entryPrice: price,
