      currentRate: latest.rate,
      avg8h: Math.round(avg8h * 1e4) / 1e4,
      avg24h: Math.round(avg24h * 1e4) / 1e4,
      annualizedPct: Math.round(latest.annualizedPct * 10) / 10,
