    trades: result.trades.length,
    sharpeRatio: round25(result.performance.sharpeRatio),
    maxDrawdownPct: round25(result.performance.maxDrawdownPct),
    profitFactor: normalizeProfitFactor(result.performance.profitFactor),
    totalPnl: round25(result.performance.totalPnl)
